<?php
declare(strict_types=1);
namespace Zandu\Modules\CashManagement\Presentation\Api;
use ApiPlatform\Metadata\Operation;use ApiPlatform\State\ProviderInterface;use InvalidArgumentException;use Zandu\Modules\CashManagement\Application\CashRegisterQueryService;use Zandu\SharedKernel\Context\CurrentActorProvider;use Zandu\SharedKernel\Identity\{CashRegisterId,StoreId,UuidFactory};use Zandu\SharedKernel\Tenancy\TenantTransaction;
/** @implements ProviderInterface<CashRegisterResource> */
final readonly class CashRegisterProvider implements ProviderInterface{public function __construct(private CurrentActorProvider $actors,private UuidFactory $uuids,private TenantTransaction $transaction,private CashRegisterQueryService $queries){}public function provide(Operation $o,array $u=[],array $c=[]):CashRegisterResource|array{$a=$this->actors->resolve();$store=$this->id($u['storeId']??null,StoreId::class);return $this->transaction->transactional($a->organizationId(),function()use($a,$o,$u,$store):CashRegisterResource|array{$v='cash_register_list'===$o->getName()?$this->queries->list($a,$store):$this->queries->get($a,$store,$this->id($u['id']??null,CashRegisterId::class));return is_array($v)&&isset($v[0])?array_map($this->resource(...),$v):$this->resource($v);});}private function resource(array $v):CashRegisterResource{return new CashRegisterResource(...array_values($v));}private function id(mixed $v,string $t):CashRegisterId|StoreId{if(!is_string($v)||''===$v)throw new InvalidArgumentException('Identifier is required.');return $t===StoreId::class?StoreId::fromString($v,$this->uuids):CashRegisterId::fromString($v,$this->uuids);}}
